static void sanitize_filename(const char *src, char *dst, size_t dst_size)
{
    size_t i;

    for (i = 0; i < dst_size - 1 && src[i] != '\0'; i++) {
        char c = src[i];
        /* Replace FAT-incompatible chars: | \ / : * ? " < > and control */
        if (c == '|' || c == '\\' || c == '/' || c == ':' ||
            c == '*' || c == '?' || c == '"' || c == '<' ||
            c == '>' || c < 0x20) {
            dst[i] = '_';
        } else {
            dst[i] = c;
        }
    }
    dst[i] = '\0';
}

static void session_path(const char *chat_id, char *buf, size_t size)
{
    char safe_id[96];

    sanitize_filename(chat_id, safe_id, sizeof(safe_id));
    snprintf(buf, size, "%s/tg_%s.jsonl", VELACLAW_SESSION_DIR, safe_id);
}

