        if (++s_append_count >= 10) {
            s_append_count = 0;
            session_truncate(chat_id, VELACLAW_SESSION_MAX_MSGS * 2);
        }
    }

    pthread_mutex_unlock(&s_session_lock);
    return OK;
}

