int memory_read_long_term(char *buf, size_t size)
{
    FILE *f = fopen(VELACLAW_MEMORY_FILE, "r");
    if (!f) {
        buf[0] = '\0';
        return ERROR;
    }
    size_t n = fread(buf, 1, size - 1, f);
    buf[n] = '\0';
    fclose(f);
    return OK;
}

int memory_write_long_term(const char *content)
{
    FILE *f = fopen(VELACLAW_MEMORY_FILE, "w");
    if (!f) {
        syslog(LOG_ERR, "[%s] Cannot write %s\n", TAG, VELACLAW_MEMORY_FILE);
        return ERROR;
    }
    fputs(content, f);
    fclose(f);
    syslog(LOG_INFO, "[%s] Long-term memory updated (%d bytes)\n", TAG, (int)strlen(content));
    return OK;
}

int memory_append_today(const char *note)
{
    char date_str[16];
    get_date_str(date_str, sizeof(date_str), 0);

    char path[128];
    snprintf(path, sizeof(path), "%s/%s.md", VELACLAW_MEMORY_DIR, date_str);

    FILE *f = fopen(path, "a");
    if (!f) {
        f = fopen(path, "w");
        if (!f) {
            syslog(LOG_ERR, "[%s] Cannot open %s\n", TAG, path);
            return ERROR;
        }
        fprintf(f, "# %s\n\n", date_str);
    }

    fprintf(f, "%s\n", note);
    fclose(f);
    return OK;
}

int memory_read_recent(char *buf, size_t size, int days)
{
    size_t offset = 0;
    buf[0] = '\0';

    for (int i = 0; i < days && offset < size - 1; i++) {
        char date_str[16];
        get_date_str(date_str, sizeof(date_str), i);

        char path[128];
        snprintf(path, sizeof(path), "%s/%s.md", VELACLAW_MEMORY_DIR, date_str);

        FILE *f = fopen(path, "r");
        if (!f) continue;

        if (offset > 0 && offset < size - 4) {
            offset += snprintf(buf + offset, size - offset, "\n---\n");
        }
        size_t n = fread(buf + offset, 1, size - offset - 1, f);
        offset += n;
        buf[offset] = '\0';
        fclose(f);
    }
    return OK;
}

