    vela_header_t hdrs[] = {
        { "x-api-key", s_api_key },
        { "X-Api-Resource-Id", VELACLAW_DOUBAO_TTS_RESOURCE },
        { "Connection", "close" },
        { NULL, NULL }
    };

    char* resp = calloc(1, VELACLAW_VOICE_RESP_BUF_SIZE);

    if (!resp) {
        free(body);
        return -ENOMEM;
