    syslog(LOG_INFO, "[%s] TTS V3 request: text=%zu bytes\n",
        TAG, strlen(text));

    size_t body_len;
    int status = vela_https_request(
        VELACLAW_DOUBAO_TTS_HOST, VELACLAW_DOUBAO_TTS_PORT,
        "POST", VELACLAW_DOUBAO_TTS_V3_PATH, hdrs,
        body, strlen(body),
        resp, VELACLAW_VOICE_RESP_BUF_SIZE, &body_len);

    free(body);
    body = NULL;

