        { "x-api-key", s_api_key },
        { "X-Api-Resource-Id", VELACLAW_DOUBAO_TTS_RESOURCE },
        { "Connection", "close" },
        { NULL, NULL }
    };

    char* resp = calloc(1, VOLC_TTS_STREAM_RESP_SIZE);

    if (!resp) {
        free(body);
        return -ENOMEM;
    }

    size_t body_len;
    int status = vela_https_request(
        VELACLAW_DOUBAO_TTS_HOST, VELACLAW_DOUBAO_TTS_PORT,
        "POST", VELACLAW_DOUBAO_TTS_V3_PATH, hdrs,
        body, strlen(body),
        resp, VOLC_TTS_STREAM_RESP_SIZE, &body_len);

    free(body);

    if (status != 200) {
        syslog(LOG_ERR, "[%s] stream: HTTP %d\n", TAG, status);
        free(resp);
        return -EIO;
    }

    if (body_len == 0) {
        free(resp);
        return -EPROTO;
