    unsigned char* pcm_tmp = malloc(VOLC_TTS_STREAM_B64_SIZE);

    if (!pcm_tmp) {
        free(resp);
        return -ENOMEM;
    }

    int chunks = 0;
    int err = 0;
    char* line = resp;

    while (line && *line) {
        while (*line == '\n' || *line == '\r' || *line == ' ') {
            line++;
        }

        if (*line == '\0') {
            break;
        }

        char* eol = strchr(line, '\n');

        if (eol) {
            *eol = '\0';
        }

        cJSON* obj = cJSON_Parse(line);

        if (!obj) {
            if (chunks > 0) {
                break; /* truncated tail, OK */
            }
            syslog(LOG_ERR, "[%s] stream: bad JSON: %.80s\n",
                TAG, line);
            err = -EPROTO;
            break;
