    free(pcm_tmp);
    free(resp);

    if (chunks == 0 && err == 0) {
        err = -EPROTO;
    }

    syslog(LOG_INFO, "[%s] stream: %d chunks delivered\n",
        TAG, chunks);
    return err;
}

