  1318	/**
  1319	 * Escape a string for safe embedding in a JSON value.
  1320	 * Handles: \\ \" \n \r \t \b \f and control chars (U+0000..U+001F).
  1321	 * Returns a malloc'd string; caller must free.  NULL on OOM.
  1322	 */
  1323	static char* json_escape_string(const char* src)
  1324	{
  1325	    if (!src)
  1326	        return NULL;
  1327	
  1328	    /* Worst case: every char becomes \uXXXX (6 bytes) */
  1329	    size_t src_len = strlen(src);
  1330	    size_t cap = src_len * 6 + 1;
  1331	    char* out = malloc(cap);
  1332	    if (!out)
  1333	        return NULL;
  1334	
  1335	    char* w = out;
  1336	    for (const char* r = src; *r; r++) {
  1337	        unsigned char c = (unsigned char)*r;
  1338	        switch (c) {
  1339	        case '"':
  1340	            *w++ = '\\';
  1341	            *w++ = '"';
  1342	            break;
  1343	        case '\\':
  1344	            *w++ = '\\';
  1345	            *w++ = '\\';
  1346	            break;
  1347	        case '\n':
  1348	            *w++ = '\\';
  1349	            *w++ = 'n';
  1350	            break;
  1351	        case '\r':
  1352	            *w++ = '\\';
  1353	            *w++ = 'r';
  1354	            break;
  1355	        case '\t':
  1356	            *w++ = '\\';
  1357	            *w++ = 't';
  1358	            break;
  1359	        case '\b':
  1360	            *w++ = '\\';
  1361	            *w++ = 'b';
  1362	            break;
  1363	        case '\f':
  1364	            *w++ = '\\';
  1365	            *w++ = 'f';
  1366	            break;
  1367	        default:
  1368	            if (c < 0x20) {
  1369	                w += sprintf(w, "\\u%04x", c);
  1370	            } else {
  1371	                *w++ = (char)c;
  1372	            }
  1373	            break;
  1374	        }
  1375	    }
  1376	    *w = '\0';
  1377	    return out;
  1378	}
