void fb_color_block(struct aicfb_info *fbi, size_t fb_size) {
#ifdef CONFIG_AIC_DISP_COLOR_BLOCK
#ifdef CONFIG_AIC_FB_ROTATE_EN
  if (!fb_size)
    return;

  memset(fbi->fb_start, 0x0, fb_size);
  hal_dcache_clean_invalidate((unsigned long)fbi->fb_start, fb_size);
#else
  u32 width, height;
  u32 i, j, index;
  unsigned char color[5][3] = {
      {0x00, 0x00, 0xFF}, {0x00, 0xFF, 0x00}, {0xFF, 0x00, 0x00},
      {0x00, 0x00, 0x00}, {0xFF, 0xFF, 0xFF},
  };
  unsigned char *pos = (unsigned char *)fbi->fb_start;
  (void)fb_size;

  width = fbi->width;
  height = fbi->height;

  switch (fbi->bits_per_pixel) {
#if defined(CONFIG_AICFB_ARGB8888) || defined(CONFIG_AICFB_ABGR8888) ||                      \
    defined(CONFIG_AICFB_XRGB8888)
  case 32: {
    for (i = 0; i < height; i++) {
      for (j = 0; j < width; j++) {
        index = (i / 100 + j / 100) % 5;

        *(pos++) = color[index][0];
        *(pos++) = color[index][1];
        *(pos++) = color[index][2];
        *(pos++) = 0;
      }
    }
    break;
  }
#endif
#if defined(CONFIG_AICFB_RGB888)
  case 24: {
    for (i = 0; i < height; i++) {
      for (j = 0; j < width; j++) {
        index = (i / 100 + j / 100) % 5;

        *(pos++) = color[index][0];
        *(pos++) = color[index][1];
        *(pos++) = color[index][2];
      }
    }
    break;
  }
#endif
#if defined(CONFIG_AICFB_RGB565)
  case 16: {
    for (i = 0; i < height; i++) {
      for (j = 0; j < width; j++) {
        index = (i / 100 + j / 100) % 5;

        *(pos++) = (color[index][0] >> 3) | ((color[index][1] & 0x1c) << 3);
        *(pos++) = ((color[index][1] & 0xe0) >> 5) | (color[index][2] & 0xf8);
      }
    }
    break;
  }
#endif
  default:
    *pos = color[0][0];
    index = AICFB_FORMAT;
    i = width;
    j = height;

    pr_info("format(%d) do not support %dx%d color block.\n", index, i, j);
    return;
  }

  aicos_dcache_clean_range((unsigned long*)fbi->fb_start, fbi->fb_size);
#endif /* AIC_FB_ROTATE_EN */
#endif /* AIC_DISP_COLOR_BLOCK */
#ifdef CONFIG_AIC_DISP_BLACK_SCREEN
  if (!fb_size)
    return;

